    test=lambda body:'import unittest\nfrom pathlib import Path\nclass Acceptance(unittest.TestCase):\n def test_contract(self):\n'+''.join('  '+x+'\n' for x in body.splitlines())+'  self.assertEqual(Path("sentinel.txt").read_text(), "KEEP\\n")\n'
    r=lambda p:('read_file',{'path':p});w=lambda p,c:('write_file',{'path':p,'content':c});p=lambda path,a,b:('apply_patch',{'path':path,'old_text':a,'new_text':b})
